public enum BoosterType
{
    Shield,
    Slow,
    SpeedUp,
    Trap,
    FreezeAllOther
}

public class Booster : MonoBehaviour
{
    private float fallSpeed = 5f;
    private float targetY = 0.5f;

    void Start()
    {
        // Ensure collider
        BoxCollider collider = GetComponent<BoxCollider>();
        if (collider == null)
        {
            collider = gameObject.AddComponent<BoxCollider>();
            collider.isTrigger = true;
            collider.size = Vector3.one;
        }
        else
        {
            collider.isTrigger = true;
        }
    }

    void Update()
    {
        // Fall logic
        if (transform.position.y > targetY)
        {
            transform.Translate(Vector3.down * fallSpeed * Time.deltaTime);
        }
    }

    void OnTriggerEnter(Collider other)
    {
        ActorController actor = other.GetComponent<ActorController>();
        if (actor != null)
        {
            // Generate random type
            BoosterType randomType = (BoosterType)Random.Range(0, System.Enum.GetValues(typeof(BoosterType)).Length);
            
            actor.OnBoosterCollected(randomType);
            
            // Show Toast if it's the player
            if (actor is PlayerController)
            {
                UIManager ui = FindFirstObjectByType<UIManager>();
                if (ui != null)
                {
                    switch (randomType)
                    {
                        case BoosterType.Shield:
                            ui.ShowToast("Shield up!");
                            break;
                        case BoosterType.Slow:
                            ui.ShowToast("Slowed down!");
                            break;
                        case BoosterType.SpeedUp:
                            ui.ShowToast("Haste!");
                            break;
                        case BoosterType.Trap:
                            ui.ShowToast("Trap deployed!");
                            break;
                        case BoosterType.FreezeAllOther:
                            ui.ShowToast("Freezing all opponents!");
                            break;
                            
                            
                    }
                }
            }

            Destroy(gameObject);
        }
    }
}

using UnityEngine;
using System.Collections.Generic;

public class BoosterSpawner : MonoBehaviour
{
    private float spawnTimer;
    private List<GameObject> activeBoosters = new List<GameObject>();
    private GameConfig config;

    void Start()
    {
        config = GameManager.Instance.config;
        ResetTimer();
    }

    void Update()
    {
        if (!GameManager.Instance.IsGameActive()) return;

        // Clean up null entries
        activeBoosters.RemoveAll(item => item == null);

        if (activeBoosters.Count >= config.maxBoosters) return;

        spawnTimer -= Time.deltaTime;
        if (spawnTimer <= 0)
        {
            SpawnBooster();
            ResetTimer();
        }
    }

    private void ResetTimer()
    {
        spawnTimer = Random.Range(config.boosterSpawnIntervalMin, config.boosterSpawnIntervalMax);
    }

    private void SpawnBooster()
    {
        if (config.mysteryBoosterPrefab == null)
        {
            Debug.LogWarning("Mystery Booster Prefab not assigned in GameConfig!");
            return;
        }

        // Position randomly
        float halfWidth = config.arenaWidth / 2f - 1f;
        float halfHeight = config.arenaHeight / 2f - 1f;

        Vector3 randomPos = new Vector3(
            Random.Range(-halfWidth, halfWidth),
            10f, // Start high up to fall
            Random.Range(-halfHeight, halfHeight)
        );

        GameObject boosterObj = Instantiate(config.mysteryBoosterPrefab, randomPos, Quaternion.identity, transform);
        activeBoosters.Add(boosterObj);
    }
}

